body.query:
query($since: GitTimestamp!, $until: GitTimestamp!, $o0: String!, $n0: String!, $o1: String!, $n1: String!, $o2: String!, $n2: String!, $o3: String!, $n3: String!, $o4: String!, $n4: String!, $o5: String!, $n5: String!, $o6: String!, $n6: String!) {
rateLimit { cost remaining resetAt }
r0: repository(owner: $o0, name: $n0) {
  isArchived
  pushedAt
  open: issues(states: OPEN) { totalCount }
  closed: issues(states: CLOSED) { totalCount }
  defaultBranchRef { target { ... on Commit {
    history(since: $since, until: $until, first: 100) {
      pageInfo { hasNextPage endCursor }
      nodes { author { name email user { login } } }
    }
  } } }
}
